import json, re
import pandas as pd
df = pd.read_parquet('/user/user1/autorlbench-runs/20261122233806-92090-2f68/workspace/data/gsm8k/main/train-00000-of-00001.parquet')
gold = {q.strip(): a.split('####')[-1].strip() for q,a in zip(df['question'], df['answer'])}
rows = [json.loads(l) for l in open('/user/user1/autorlbench-runs/20261122233806-92090-2f68/workspace/results/rollouts.jsonl')]
FINAL = re.compile(r"####\s*\$?\s*(-?[\d,]*\.?\d+)")
def norm(x):
    x = x.replace(',', '').strip().rstrip('.')
    try: v = float(x)
    except ValueError: return x
    return str(int(v)) if v == int(v) else str(v)

by_step = {}
for r in rows: by_step.setdefault(r['step'], []).append(r)

mis_steps = 0; clean_steps = 0
for s, g in sorted(by_step.items()):
    expected = []
    for r in g:
        q = r['prompt'].split('user\n')[-1].rsplit('\nassistant', 1)[0].strip()
        m = FINAL.search(r['completion'])
        pred = norm(m.group(1)) if m else None
        expected.append(1.0 if (pred is not None and pred == norm(gold[q])) else 0.0)
    logged = [r['reward'] for r in g]
    if expected != logged:
        mis_steps += 1
        if mis_steps <= 4:
            print(f'--- step {s}: expected={expected} logged={logged}')
            # try shifts
            for shift in range(-2,3):
                sh = logged[shift:] + logged[:shift] if shift else logged
                if sh == expected: print(f'    matches with shift {shift}')
            # try reversal
            if logged[::-1] == expected: print('    matches REVERSED')
            # try swap within pairs
            paired = []
            for i in range(0,8,2): paired.extend([logged[i+1], logged[i]])
            if paired == expected: print('    matches PAIR-SWAPPED')
    else:
        clean_steps += 1
print(f'misassigned steps: {mis_steps}, clean steps: {clean_steps}')
